figures=''.join(f'<article id="{name}"><h2>{title}</h2><a href="combined-renders/{name}.png" target="_blank"><img src="combined-renders/{name}.png" width="1600" height="1067" loading="lazy" alt="{title}"></a><p>{text}</p></article>' for name,title,text in views)
